@@ -30,6 +35,9 @@ QString viewService()
 AppMenuApplet::AppMenuApplet(QObject *parent, const KPluginMetaData &data, const QVariantList &args)
     : Plasma::Applet(parent, data, args)
 {
+    s_instances.append(this);
+    setupShortcuts();
+
     ++s_refs;
     // if we're the first, register the service
     if (s_refs == 1) {
@@ -61,7 +69,42 @@ AppMenuApplet::AppMenuApplet(QObject *parent, const KPluginMetaData &data, const
     });
 }

-AppMenuApplet::~AppMenuApplet() = default;
+AppMenuApplet::~AppMenuApplet()
+{
+    s_instances.removeAll(this);
+}
+
+void AppMenuApplet::setupShortcuts()
+{
+    static QAction *searchAction = nullptr;
+    if (searchAction) {
+        return;
+    }
+
+    searchAction = new QAction(QCoreApplication::instance());
+    searchAction->setObjectName(QStringLiteral("search application menu"));
+    searchAction->setText(i18n("Search Application Menu"));
+    searchAction->setIcon(QIcon::fromTheme(QStringLiteral("search")));
+    connect(searchAction, &QAction::triggered, searchAction, [] {
+        for (AppMenuApplet *instance : std::as_const(s_instances)) {
+            if (instance->activateSearch()) {
+                return;
+            }
+        }
+    });
+    KGlobalAccel::self()->setGlobalShortcut(searchAction, QKeySequence());
+}
+
+bool AppMenuApplet::activateSearch()
+{
+    auto *model = qobject_cast<AppMenuModel *>(m_model);
+    if (destroyed() || view() != FullView || !model || !model->searchAvailable()) {
+        return false;
+    }
+
+    Q_EMIT requestActivateIndex(model->rowCount() - 1);
+    return true;
+}

 void AppMenuApplet::init()
 {
